// GENERATED BY SYMPLRV3 — DO NOT EDIT
// Cross-screen selected values (country pickers, option sheets). A selection
// screen writes with setAppValue(); any widget with props.valueKey re-renders
// through useAppValue(). In-memory by design: selections are per-run state.
import React from 'react';

const values = new Map<string, string>();
const subs = new Map<string, Set<() => void>>();

export function setAppValue(key: string, value: string): void {
  values.set(key, value);
  for (const fn of subs.get(key) ?? []) fn();
}

export function getAppValue(key: string): string | undefined {
  return values.get(key);
}

/**
 * Subscribe with useSyncExternalStore, not an effect.
 *
 * The effect version subscribed AFTER render committed and read
 * `values.get(key)` during render, which loses any write published in that
 * window: a selection screen that calls setAppValue() and navigates back in the
 * same tick notified a subscriber list the returning widget had not joined yet,
 * so the widget rendered the previous value and never re-rendered. It is also
 * the documented tearing hazard under concurrent rendering — two widgets
 * reading the same key mid-transition can commit different values.
 *
 * useSyncExternalStore is React's answer to exactly this: it subscribes before
 * paint and re-reads the snapshot at the right point in the commit.
 */
export function useAppValue(key: string): string | undefined {
  const subscribe = React.useCallback(
    (onChange: () => void) => {
      let set = subs.get(key);
      if (!set) {
        set = new Set();
        subs.set(key, set);
      }
      set.add(onChange);
      return () => {
        set.delete(onChange);
      };
    },
    [key],
  );
  return React.useSyncExternalStore(
    subscribe,
    () => values.get(key),
    () => values.get(key),
  );
}

/**
 * Route params, remembered for the rest of the run.
 *
 * A multi-step capture flow navigates once PER STEP, and each hop carries only
 * the value that step produced: front capture -> review(front), back capture ->
 * review(back). React Navigation replaces params on each navigate, so by the
 * second review the front uri is simply gone and a thumbnail reading
 * route.params.front rendered blank. (NavParam has no kind that forwards an
 * INCOMING param, so the edge itself cannot re-send it.)
 *
 * Every screen mirrors the params it receives into the app store, and a
 * {param:x} read falls back to that store when the CURRENT route has no x. The
 * live param always wins, so a step that re-captures overwrites the stale value
 * rather than reviving it.
 *
 * Only non-empty strings are kept: a param arriving empty must not clobber a
 * good remembered value, and must not resurrect one either.
 */
export function rememberParams(params: unknown): void {
  if (!params || typeof params !== 'object') return;
  for (const [k, v] of Object.entries(params as Record<string, unknown>)) {
    if (typeof v === 'string' && v !== '') values.set('param:' + k, v);
  }
}

/** The live route param if present, else the remembered one. */
export function recallParam(params: unknown, key: string): string {
  const live = (params as Record<string, unknown> | undefined)?.[key];
  if (typeof live === 'string' && live !== '') return live;
  return values.get('param:' + key) ?? '';
}
